/**
 * The sport losing the most money, when it has cost at least $50 over 5+ bets
 * @nullable
 */
export type LeakProfileWorstSport = {
  sport: string;
  /** Net loss in dollars (negative number) */
  netLoss: number;
  bets: number;
  /** Net dollars in this sport over the recent window (negative = still losing) */
  recentNet: number;
  /** Settled bets in this sport inside the recent window */
  recentBets: number;
} | null;

/**
 * Present when 7+ confidence plays hit under 45% across 5+ samples
 * @nullable
 */
export type LeakProfileOverconfidence = {
  /** Win percentage of high-confidence (7+) settled plays */
  winRate: number;
  sample: number;
  /**
     * Win percentage of high-confidence plays settled inside the recent window (null when none)
     * @nullable
     */
  recentWinRate: number | null;
  /** High-confidence plays settled inside the recent window */
  recentSample: number;
} | null;

/**
 * Most common self-graded miss reason across settled losses (excluding normal variance)
 * @nullable
 */
export type LeakProfileTopMissReason = {
  reason: string;
  count: number;
  netLoss: number;
  /** Losses graded with this reason inside the 14-day mistake window */
  recentCount: number;
  /** Dollars lost to this reason inside the 14-day mistake window */
  recentNetLoss: number;
  /** Length in days of the rolling window used for recentCount and recentNetLoss (always 14) */
  mistakeWindowDays: number;
} | null;

/**
 * Present when the bettor looks mid-tilt right now: at least two settled losses inside the short window, followed by a burst of rapid plays at escalated stakes relative to their own baseline. Null when data is thin (needs a real avgStake baseline) or the pattern is absent.
 * @nullable
 */
export type LeakProfileTiltSpiral = {
  /** Length of the "right now" window the signal looks at */
  windowHours: number;
  /** Settled losses (bets + parlays) inside the window */
  recentLosses: number;
  /** Plays logged since the first of those losses landed */
  rapidPlays: number;
  /** Average stake across the rapid plays */
  burstAvgStake: number;
  /** burstAvgStake divided by the bettor's baseline average stake */
  stakeRatio: number;
  /**
     * Total stake lost across all detected tilt sessions in the last 90 days (null when fewer than two tilt sessions are detected). Shown on the tilt card to make the recurring cost concrete — "your last N tilt nights cost you $X".
     * @nullable
     */
  tiltCostDollars: number | null;
  /** Number of distinct tilt sessions detected in the last 90 days (each session is a 12-hour window with 2+ settled losses). Includes the current active spiral when one is present. */
  tiltEventCount: number;
} | null;

export interface LeakProfile {
  /** Settled straight bets counted toward the profile */
  settledCount: number;
  /** Length in days of the recent window used for every recent* figure */
  recentWindowDays: number;
  /**
     * Average stake across settled straight bets (null under 5 samples)
     * @nullable
     */
  avgStake: number | null;
  /**
     * ISO timestamp of the most recent settled loss (bet or parlay)
     * @nullable
     */
  lastLossAt: string | null;
  /**
     * The sport losing the most money, when it has cost at least $50 over 5+ bets
     * @nullable
     */
  worstSport: LeakProfileWorstSport;
  /**
     * Present when 7+ confidence plays hit under 45% across 5+ samples
     * @nullable
     */
  overconfidence: LeakProfileOverconfidence;
  /**
     * Most common self-graded miss reason across settled losses (excluding normal variance)
     * @nullable
     */
  topMissReason: LeakProfileTopMissReason;
  /**
     * Present when the bettor looks mid-tilt right now: at least two settled losses inside the short window, followed by a burst of rapid plays at escalated stakes relative to their own baseline. Null when data is thin (needs a real avgStake baseline) or the pattern is absent.
     * @nullable
     */
  tiltSpiral: LeakProfileTiltSpiral;
  /** True while the one-time "trend flipped" celebration is available: the reported leak's trend reads non-negative and the user has not yet seen the celebratory card. Reading this endpoint never consumes the celebration — clients that render the card must POST /users/me/leak-celebration-seen, after which responses return false and the celebration never repeats. */
  trendFlip: boolean;
  /**
     * Where this bettor's ROI sits against the anonymous peer pool — one of top_10, top_25, median, bottom_25, bottom_10. Null when the bettor opted out of benchmarks, the peer pool is too small (under 5 contributors), or the bettor has no computable ROI yet.
     * @nullable
     */
  roiBand: string | null;
}

export interface EdgeFinderLane {
  /** Stable lane key within its dimension (e.g. "NBA", "favorite", "heavy_fav", "mon", "heavy") */
  key: string;
  wins: number;
  losses: number;
  pushes: number;
  /** Settled bets in this lane (the sample size) */
  bets: number;
  /** Total dollars staked in this lane */
  wagered: number;
  /** Net dollars won or lost in this lane */
  netProfit: number;
  /** Net profit as a percentage of dollars wagered */
  roi: number;
}

export interface EdgeFinder {
  /** Settled straight bets with valid odds counted toward the lanes */
  settledCount: number;
  /** Minimum bets a lane needs before its numbers mean anything */
  minSample: number;
  /**
     * Average stake used to draw the stake-band boundaries (null when no settled bets)
     * @nullable
     */
  avgStake: number | null;
  sport: EdgeFinderLane[];
  /** Lanes keyed "favorite" (odds -100 and under) and "underdog" (+100 and over) */
  favDog: EdgeFinderLane[];
  /** Lanes keyed "heavy_fav" (-200 and under), "fav" (-199 to -100), "dog" (+100 to +199), "long_shot" (+200 and over) */
  oddsBand: EdgeFinderLane[];
  /** Lanes keyed "mon" through "sun" from the game date (UTC) */
  dayOfWeek: EdgeFinderLane[];
  /** Lanes keyed "light" (under 0.75x average stake), "standard" (0.75x to 1.5x), "heavy" (over 1.5x) */
  stakeBand: EdgeFinderLane[];
}

